import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();

  // Create a simple plane mesh
  const planeGeom = new PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial();
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load and apply texture if an image URL is provided
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        planeMat.map = tex;
        planeMat.needsUpdate = true;
        // Store texture for disposal
        cleanupResources.texture = tex;
      })
      .catch(() => {
        // Silently ignore texture load failures
      });
  }

  // Render text content via the font atlas
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.colors && config.colors.ink) || '#16161d',
      align: 'center',
    });
    // Slight offset to avoid Z‑fighting with the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // Apply any cinematic primitives declared in the config
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim && typeof prim.name === 'string' && ctx.primitives[prim.name]) {
        const handle = ctx.primitives[prim.name](root, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // Store resources that need explicit disposal
  const cleanupResources = {
    geometry: planeGeom,
    material: planeMat,
    texture: null,
    timelines: [], // No GSAP timelines in this node
    primitives: primitiveHandles,
    texts: textObjects,
  };

  // Expose empty interaction handlers (no interactions specified)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitive resources
    for (const ph of cleanupResources.primitives) {
      if (ph && typeof ph.cleanup === 'function') {
        ph.cleanup();
      }
    }

    // Kill any GSAP timelines (none are created here)
    for (const tl of cleanupResources.timelines) {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    }

    // Dispose texture, material, and geometry
    if (cleanupResources.texture) {
      cleanupResources.texture.dispose();
    }
    cleanupResources.material.dispose();
    cleanupResources.geometry.dispose();

    // Dispose any text objects (geometry/material they may hold)
    for (const txt of cleanupResources.texts) {
      txt.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      });
    }
  };

  return root;
}
